class MessageModel { const MessageModel({required this.id,required this.senderId,required this.type,required this.createdAt,this.text,this.attachmentUrl,this.attachmentName,this.replyToMessageId,this.status=MessageStatus.sent}); final String id,senderId; final MessageType type; final DateTime createdAt; final String? text,attachmentUrl,attachmentName,replyToMessageId; final MessageStatus status; factory MessageModel.fromFirestore(DocumentSnapshot<Map<String,Object?>> d)=>MessageModel(id:d.id,senderId:d['senderId'] as String,type:MessageType.values.byName(d['type'] as String),createdAt:dateFromValue(d['createdAt'])!,text:d['text'] as String?,attachmentUrl:d['attachmentUrl'] as String?,attachmentName:d['attachmentName'] as String?,replyToMessageId:d['replyToMessageId'] as String?,status:MessageStatus.values.byName(d['status'] as String? ?? 'sent')); Map<String,Object?> toFirestore()=>{'senderId':senderId,'type':type.value,'createdAt':Timestamp.fromDate(createdAt),'text':text,'attachmentUrl':attachmentUrl,'attachmentName':attachmentName,'replyToMessageId':replyToMessageId,'status':status.value}; }
